/* =========================================================
   EL ARO — costura roja/blanca con banda negra a todo el ancho
   del marco. El contenido (foto/ícono) va SIEMPRE afuera de la
   capa que gira/respira, como hermano y no como hijo: por eso
   nunca se mueve junto con el aro.
   ========================================================= */

function PokeRing({ size = 220, thickness = 11, active = true, spinTrigger = 0, breathing = false, children }) {
    const r = (size - thickness) / 2;
    const cx = size / 2;
    const cy = size / 2;
    const bandH = thickness * 1.25;
    const bandHalfW = r + thickness / 2;

    return (
        <div
            className="relative shrink-0"
            style={{
                width: size,
                height: size,
                filter: active ? "none" : "grayscale(0.85)",
                opacity: active ? 1 : 0.45,
                transition: "filter 260ms var(--ease-out), opacity 260ms var(--ease-out)",
            }}
        >
            <div key={`ring-${spinTrigger}`} className={spinTrigger > 0 ? "spin-once" : ""} style={{ position: "absolute", inset: 0 }}>
                <div className={breathing ? "photo-breathe" : ""} style={{ position: "absolute", inset: 0 }}>
                    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="absolute inset-0" style={{ pointerEvents: "none" }}>
                        <circle cx={cx} cy={cy} r={r} fill="none" stroke="#18171c" strokeWidth="2" />
                        <path d={`M ${cx - r} ${cy} A ${r} ${r} 0 0 1 ${cx + r} ${cy}`} stroke="var(--ember)" strokeWidth={thickness} fill="none" strokeLinecap="butt" />
                        <path d={`M ${cx + r} ${cy} A ${r} ${r} 0 0 1 ${cx - r} ${cy}`} stroke="#fdfdfc" strokeWidth={thickness} fill="none" strokeLinecap="butt" />
                        <rect x={cx - bandHalfW} y={cy - bandH / 2} width={bandHalfW * 2} height={bandH} fill="#18171c" />
                    </svg>
                </div>
            </div>

            <div
                className="absolute rounded-full overflow-hidden flex items-center justify-center"
                style={{ inset: thickness * 1.05, background: "var(--surface)" }}
            >
                {children}
            </div>
        </div>
    );
}

