function Pill({ children }) {
    return <span className="pill">{children}</span>;
}

function LangToggle({ lang, setLang, label }) {
    return (
        <div className="lang-toggle flex items-center rounded-full" style={{ background: "var(--surface)" }} aria-label={label}>
            <button onClick={() => setLang("es")} className={`lang-btn ${lang === "es" ? "lang-btn-active" : ""}`}>ES</button>
            <button onClick={() => setLang("en")} className={`lang-btn ${lang === "en" ? "lang-btn-active" : ""}`}>EN</button>
        </div>
    );
}

function StackSelector({ lang }) {
    const [active, setActive] = useState(STACK[0].id);
    const [spin, setSpin] = useState(0);
    const playSound = useSelectSound();
    const current = STACK.find((s) => s.id === active);

    const pick = (id) => {
        if (id !== active) setActive(id);
        setSpin((n) => n + 1);
        playSound();
    };

    return (
        <div>
            <div className="flex flex-wrap justify-center gap-6 md:gap-8 mb-8">
                {STACK.map((s) => {
                    const Icon = s.icon;
                    const isActive = s.id === active;
                    return (
                        <button
                            key={s.id}
                            onClick={() => pick(s.id)}
                            aria-pressed={isActive}
                            className="stack-btn flex flex-col items-center gap-2"
                            style={{ background: "none", border: "none", cursor: "pointer", padding: 0 }}
                        >
                            <PokeRing size={64} thickness={5} active={isActive} spinTrigger={isActive ? spin : 0} breathing={false}>
                                <Icon size={22} color={isActive ? "var(--text)" : "var(--text-secondary)"} strokeWidth={1.6} />
                            </PokeRing>
                            <span
                                className="text-xs font-mono text-center"
                                style={{ color: isActive ? "var(--ember)" : "var(--text-secondary)", fontWeight: isActive ? 700 : 500, maxWidth: 92 }}
                            >
                {s.label[lang]}
              </span>
                        </button>
                    );
                })}
            </div>

            <div key={active} className="max-w-2xl mx-auto">
                <p className="reveal text-sm leading-relaxed mb-5" style={{ color: "var(--text-secondary)" }}>
                    {current.blurb[lang]}
                </p>
                <div className="flex flex-wrap justify-center gap-2">
                    {current.items[lang].map((item, i) => (
                        <span key={item} className="reveal" style={{ animationDelay: `${i * 40}ms` }}>
              <Pill>{item}</Pill>
            </span>
                    ))}
                </div>
            </div>
        </div>
    );
}

function ProjectGallery({ images = [], discord = false, FallbackIcon, prevLabel, nextLabel }) {
    const [idx, setIdx] = useState(0);
    if (discord) {
        return (
            <div className="flex items-center justify-center relative" style={{ height: 88, background: "var(--surface-2)" }}>
                <DiscordIcon size={30} color="var(--text-secondary)" />
            </div>
        );
    }
    if (!images.length) {
        return (
            <div className="flex items-center justify-center relative" style={{ height: 88, background: "var(--surface-2)" }}>
                <FallbackIcon size={28} color="var(--text-secondary)" strokeWidth={1.4} />
            </div>
        );
    }
    const next = (e) => { e.stopPropagation(); setIdx((i) => (i + 1) % images.length); };
    const prev = (e) => { e.stopPropagation(); setIdx((i) => (i - 1 + images.length) % images.length); };
    return (
        <div className="relative overflow-hidden" style={{ height: 170, background: "var(--surface-2)" }}>
            <img src={images[idx]} alt="" className="w-full h-full" style={{ objectFit: "cover" }} />
            {images.length > 1 && (
                <>
                    <button onClick={prev} aria-label={prevLabel} className="gallery-arrow" style={{ left: 8 }}>‹</button>
                    <button onClick={next} aria-label={nextLabel} className="gallery-arrow" style={{ right: 8 }}>›</button>
                    <span className="gallery-counter">{idx + 1} / {images.length}</span>
                </>
            )}
        </div>
    );
}

